"""Derived answers and staged methods for every numbered supplied physics problem."""
SPECS={}
def a(n,ans,unit,formula,reason,**kw):SPECS[n]=dict(ans=ans,unit=unit,formula=formula,reason=reason,**kw)
def fields(n,values,formula,reason,**kw):SPECS[n]=dict(values=values,formula=formula,reason=reason,**kw)
def review(n,formula,reason,key,conclusion,**kw):SPECS[n]=dict(review=True,formula=formula,reason=reason,key=key,conclusion=conclusion,**kw)
